def transform(grid):
    """Repeat the contents before a solid separator line across later sections."""
    h, w = len(grid), len(grid[0])
    background = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    candidates = []
    for axis, n, m in [('row', h, w), ('col', w, h)]:
        lines = []
        for i in range(n):
            vals = [grid[i][j] for j in range(m)] if axis == 'row' else [grid[j][i] for j in range(m)]
            if vals[0] != background and all(v == vals[0] for v in vals):
                lines.append(i)
        if lines:
            candidates.append((len(lines), axis, lines))
    if not candidates:
        return [row[:] for row in grid]
    _, axis, dividers = max(candidates, key=lambda x: (x[0], x[1] == 'row'))
    n = h if axis == 'row' else w
    m = w if axis == 'row' else h
    start = dividers[0]
    period = dividers[1] - start if len(dividers) > 1 else start + 1
    source_len = start
    out = [row[:] for row in grid]
    # Tile the source section after each separator, leaving divider lines intact.
    for dest in range(start + period, n, period):
        for offset in range(source_len):
            src_idx = offset
            dst_idx = dest + offset
            if dst_idx >= n:
                break
            for j in range(m):
                if axis == 'row':
                    out[dst_idx][j] = grid[src_idx][j]
                else:
                    out[j][dst_idx] = grid[j][src_idx]
    # With a single divider, the next section begins one line after it.
    if len(dividers) == 1:
        dest = start + 1
        while dest < n:
            for offset in range(source_len):
                dst_idx = dest + offset
                if dst_idx >= n:
                    break
                for j in range(m):
                    if axis == 'row':
                        out[dst_idx][j] = grid[offset][j]
                    else:
                        out[j][dst_idx] = grid[j][offset]
            dest += source_len + 1
    return out
