def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = [sum(cell == c for row in grid for cell in row) for c in range(10)]
    background = max(range(10), key=lambda c: counts[c])

    # A uniform non-background row or column is a panel divider.
    options = []
    for axis, n, m in [('row', h, w), ('col', w, h)]:
        dividers = []
        for i in range(n):
            line = [grid[i][j] for j in range(m)] if axis == 'row' else [grid[j][i] for j in range(m)]
            if line[0] != background and all(x == line[0] for x in line):
                dividers.append(i)
        if dividers:
            options.append((len(dividers), axis, dividers, n))
    if not options:
        return [row[:] for row in grid]
    _, axis, dividers, n = max(options, key=lambda x: (x[0], x[1] == 'row'))

    # Split into equally sized panels, excluding divider lines.
    spans = []
    start = 0
    for d in dividers:
        if d > start:
            spans.append((start, d))
        start = d + 1
    if start < n:
        spans.append((start, n))
    if len(spans) < 2:
        return [row[:] for row in grid]
    size = min(b - a for a, b in spans)
    # Require matching panel dimensions, as indicated by the divider layout.
    if any(b - a != size for a, b in spans):
        return [row[:] for row in grid]

    out = [row[:] for row in grid]
    other = w if axis == 'row' else h
    for offset in range(size):
        for j in range(other):
            vals = []
            for a, _ in spans:
                v = grid[a + offset][j] if axis == 'row' else grid[j][a + offset]
                if v != background:
                    vals.append(v)
            if vals:
                # Transfer every observed foreground color to the corresponding
                # cell of every panel; existing non-background cells are retained.
                for a, _ in spans:
                    if axis == 'row':
                        out[a + offset][j] = vals[0]
                    else:
                        out[j][a + offset] = vals[0]
    return out
